import React, { useState, useEffect } from "react";
import "./brutalist-button.css";

export default function ValentineApp() {
    const [page, setPage] = useState("home");
    const [userName, setUserName] = useState("");
    const [selectedColor, setSelectedColor] = useState("");

    return (
        <div className="valentine-container">

            {/* Floating Hearts */}
            <div className="wrapper">
                <div className="heart x1"></div>
                <div className="heart x2"></div>
                <div className="heart x3"></div>
                <div className="heart x4"></div>
                <div className="heart x5"></div>
                <div className="altheart x6"></div>
            </div>

            {/* Routing */}
            {page === "home" && <HomePage onYes={() => setPage("game")} />}
            {page === "game" && <DinoGamePage onFinish={() => setPage("input")} />}

            {page === "input" && (
                <InputPage
                    userName={userName}
                    setUserName={setUserName}
                    selectedColor={selectedColor}
                    setSelectedColor={setSelectedColor}
                    onSubmit={() => setPage("final")}
                />
            )}

            {page === "final" && (
                <FinalPage
                    userName={userName}
                    selectedColor={selectedColor}
                />
            )}

            {/* Styles */}
            <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@400;600;700&display=swap');

