          opacity: 0.3;
          animation: move 12s linear infinite, side 2s ease-in-out infinite alternate;
        }

        .x6 {
          left: 33%;
          animation: move 10s linear infinite, sway 6s ease-in-out infinite alternate;
        }

        @keyframes move {
          from { top: 100%; }
          to { top: -200px; }
        }

        @keyframes side {
          from { margin-left: 0; }
          to { margin-left: 50px; }
        }

        @keyframes sway {
          0% { transform: rotate(12deg); }
          50% { transform: rotate(-5deg); }
          100% { transform: rotate(0deg); }
        }

        .heart:before,
        .heart:after {
